    static func encloses(_ outer:[CGPoint], actualV3:[CGPoint]) -> Bool {
        guard outer.count==4,actualV3.count==4,
              (outer+actualV3).allSatisfy({$0.x.isFinite && $0.y.isFinite}) else {return false}
        func cross(_ a:CGPoint,_ b:CGPoint,_ p:CGPoint)->CGFloat {
            (b.x-a.x)*(p.y-a.y)-(b.y-a.y)*(p.x-a.x)
        }
        func orientation(_ q:[CGPoint])->CGFloat? {
            var sign:CGFloat=0
            for i in 0..<4 {
                let z=cross(q[i],q[(i+1)%4],q[(i+2)%4])
                guard z.isFinite,abs(z)>1e-12 else {return nil}
                let s:CGFloat=z>0 ? 1 : -1
                if sign != 0 && sign != s {return nil};sign=s
            }
            return sign
        }
        guard let sign=orientation(outer),orientation(actualV3) != nil else {return false}
        for i in 0..<4 {
            let a=outer[i],b=outer[(i+1)%4],len=hypot(b.x-a.x,b.y-a.y)
            guard len.isFinite,len>0 else {return false}
            for p in actualV3 where sign*cross(a,b,p)/len < -1e-7 {return false}
        }
        return true
    }
